<script setup>
import AppShell from '../../Layouts/AppShell.vue'
import StateCard from '../../Components/StateCard.vue'
import PhotoSelector from '../../Components/PhotoSelector.vue'
import UploadProgress from '../../Components/UploadProgress.vue'
import UploadModal from '../../Components/UploadModal.vue'
import { Head, Link, router, useForm } from '@inertiajs/vue3'
import QRCode from 'qrcode'
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
const props = defineProps({ group: Object, canManage: Boolean, canUpload: Boolean, photos: Object, tabs: Array, activeTab: String, branding: Object, photoUploadLimits: Object })
const maxUploadFileMb=computed(()=>Number(props.photoUploadLimits?.maxFileMb||30)),maxUploadFileBytes=computed(()=>maxUploadFileMb.value*1048576),maxUploadBatchFiles=computed(()=>Number(props.photoUploadLimits?.maxBatchFiles||50))
const selected = ref([]), exportForm = useForm({ photo_ids: [] })
const selectionMode=ref(false),busyFavourites=ref(new Set()),busyDownloads=ref(new Set()),sharing=ref(false),shareOpen=ref(false),shareOptionsOpen=ref(false),guideOpen=ref(false),shareUrl=ref(''),invitation=ref(null),shareError=ref(''),copyFeedback=ref(''),inviteCopying=ref(false),inviteCopied=ref(false),inviteCopyError=ref(''),inviteCopyTimer=ref(null),shareDialog=ref(null),shareTrigger=ref(null),qrOpen=ref(false),qrData=ref(''),qrDialog=ref(null),qrTrigger=ref(null),qrCopyStatus=ref('idle'),qrCopyTimer=ref(null),qrDownloadStatus=ref('idle'),qrDownloadTimer=ref(null),toast=ref(''),storageKey=`lenspic:gallery-selection:${props.group.id}`,scrollKey=`lenspic:gallery-scroll:${props.group.id}`
const uploadOpen=ref(false),uploadTrigger=ref(null),fileInput=ref(null),dragActive=ref(false),uploadFiles=ref([]),transferProgress=ref(0),transferring=ref(false),upload=ref(null),uploadError=ref(''),pollTimer=ref(null),activeRequests=ref(new Set()),uploadBatchIds=ref([]),seenReady=new Set()
const uploadConcurrency=computed(()=>Math.max(2,Math.min(4,Number(props.photoUploadLimits?.concurrency||3))))
const allLoadedSelected = computed(() => props.photos.data.length > 0 && props.photos.data.every(photo=>selected.value.includes(photo.id)))
const eventDate = computed(() => props.group.event_date ? new Intl.DateTimeFormat(undefined, { dateStyle: 'long' }).format(new Date(props.group.event_date)) : 'Date not set')
function toggleLoaded(){ const loaded=props.photos.data.map(photo=>photo.id);selected.value=allLoadedSelected.value?selected.value.filter(id=>!loaded.includes(id)):[...new Set([...selected.value,...loaded])] }
function togglePhoto(photo,checked){selected.value=checked?[...new Set([...selected.value,photo.id])]:selected.value.filter(id=>id!==photo.id)}
function clearSelection(){selected.value=[];selectionMode.value=false}
function makeExport(){ exportForm.photo_ids=[...selected.value]; exportForm.post(`/groups/${props.group.id}/exports`,{onSuccess:()=>selected.value=[]}) }
function shareFailureMessage(error){if(error?.status===401)return'Please sign in again to share this Group.';if(error?.status===403)return'You do not have permission to share this Group.';if(error?.status===404)return'The Group could not be found.';if(error?.status===409)return'Group sharing is currently disabled.';if(error?.status===419)return'Your session expired. Refresh the page and try again.';if(error?.status===422&&error?.safeMessage)return error.safeMessage;if(error?.status===500)return'The invitation could not be created. Please try again.';return'The invitation could not be created. Please try again.'}
async function shareCurrentGroup(){if(sharing.value||!props.group.can_share_group)return;shareOpen.value=true;shareOptionsOpen.value=false;guideOpen.value=false;shareError.value='';invitation.value=null;sharing.value=true;await nextTick();shareDialog.value?.querySelector('button')?.focus();try{const response=await fetch(props.group.share_endpoint,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content}}),body=await response.json().catch(()=>({}));if(!response.ok){if(import.meta.env.DEV)console.error('Gallery Group share request failed',{groupId:props.group.id,status:response.status});const error=new Error('Share request failed');error.status=response.status;error.safeMessage=typeof body.message==='string'?body.message:null;throw error}if(!body.success||!body.invitation?.share_url)throw Object.assign(new Error('Invalid invitation response'),{status:500});invitation.value=body.invitation;shareUrl.value=body.invitation.share_url}catch(error){shareError.value=shareFailureMessage(error)}finally{sharing.value=false}}
function closeShare(){if(sharing.value||qrOpen.value)return;shareOpen.value=false;shareOptionsOpen.value=false;guideOpen.value=false;inviteCopied.value=false;inviteCopyError.value='';clearTimeout(inviteCopyTimer.value);nextTick(()=>(shareTrigger.value||document.querySelector('button[aria-label="Share Group"]'))?.focus())}
async function copyText(value,label){try{await navigator.clipboard.writeText(value);copyFeedback.value=label}catch{copyFeedback.value='Select the value and copy it manually.'}setTimeout(()=>copyFeedback.value='',2200)}
async function copyGroupLink(){await copyText(shareUrl.value,'Link copied')}
async function copyInviteLink(){if(inviteCopying.value||!invitation.value?.share_url)return;inviteCopying.value=true;inviteCopyError.value='';clearTimeout(inviteCopyTimer.value);try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(invitation.value.share_url);else{const textarea=document.createElement('textarea');textarea.value=invitation.value.share_url;textarea.readOnly=true;textarea.setAttribute('aria-hidden','true');textarea.style.cssText='position:fixed;left:-9999px;top:0';document.body.appendChild(textarea);textarea.select();let copied=false;try{copied=document.execCommand('copy')}finally{textarea.remove()}if(!copied)throw new Error('Clipboard fallback failed')}inviteCopied.value=true;inviteCopyTimer.value=setTimeout(()=>inviteCopied.value=false,2000)}catch(error){inviteCopied.value=false;inviteCopyError.value='Could not copy the link. Please try again.';if(import.meta.env.DEV)console.error('Gallery invitation copy failed',{groupId:props.group.id,clipboardAvailable:Boolean(navigator.clipboard?.writeText),errorName:error?.name||'Error'})}finally{inviteCopying.value=false}}
function invitationText(){return `You’re invited to join the LensPic Group “${props.group.name}”.\n\nOpen the Group:\n${shareUrl.value}\n\nInvitation code: ${invitation.value?.code||''}`}
function shareGroupWhatsApp(){if(!props.group.can_share_group||!invitation.value?.share_url)return;const anchor=document.createElement('a');anchor.href=`https://wa.me/?text=${encodeURIComponent(invitationText())}`;anchor.target='_blank';anchor.rel='noopener noreferrer';anchor.click()}
function shareGroupEmail(){location.href=`mailto:?subject=${encodeURIComponent(`Join ${props.group.name} on LensPic`)}&body=${encodeURIComponent(invitationText())}`}
async function shareThroughDevice(){if(!navigator.share)return;try{await navigator.share({title:`Join ${props.group.name} on LensPic`,text:invitationText(),url:shareUrl.value})}catch(error){if(error?.name!=='AbortError')shareError.value='Device sharing is unavailable. Copy the invitation link instead.'}}
async function printQr(){if(!invitation.value||qrOpen.value)return;qrOpen.value=true;qrCopyStatus.value='idle';qrDownloadStatus.value='idle';clearTimeout(qrCopyTimer.value);clearTimeout(qrDownloadTimer.value);try{qrData.value=await QRCode.toDataURL(shareUrl.value,{width:1024,margin:4,errorCorrectionLevel:'H',type:'image/png'});await nextTick();qrDialog.value?.querySelector('button')?.focus()}catch{qrOpen.value=false;shareError.value='The QR code could not be generated. Please try again.'}}
function closeQr(){qrOpen.value=false;qrCopyStatus.value='idle';qrDownloadStatus.value='idle';clearTimeout(qrCopyTimer.value);clearTimeout(qrDownloadTimer.value);nextTick(()=>{const trigger=qrTrigger.value||[...shareDialog.value?.querySelectorAll('button')||[]].find(button=>button.textContent.trim()==='Print QR');trigger?.focus()})}
async function copyQrLink(){if(qrCopyStatus.value==='copying'||!invitation.value?.share_url)return;clearTimeout(qrCopyTimer.value);qrCopyStatus.value='copying';try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(invitation.value.share_url);else{const textarea=document.createElement('textarea');textarea.value=invitation.value.share_url;textarea.readOnly=true;textarea.setAttribute('aria-hidden','true');textarea.style.cssText='position:fixed;left:-9999px;top:0';document.body.appendChild(textarea);textarea.select();let copied=false;try{copied=document.execCommand('copy')}finally{textarea.remove()}if(!copied)throw new Error('Clipboard fallback failed')}qrCopyStatus.value='success';qrCopyTimer.value=setTimeout(()=>qrCopyStatus.value='idle',2400)}catch(error){qrCopyStatus.value='error';if(import.meta.env.DEV)console.error('Gallery QR invitation copy failed',{groupId:props.group.id,clipboardAvailable:Boolean(navigator.clipboard?.writeText),errorName:error?.name||'Error'})}}
function qrFilename(){const slug=String(props.group.name||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80);return slug?`lenspic-${slug}-group-invite-qr.png`:'lenspic-group-invite-qr.png'}
async function downloadInvitationQr(){if(qrDownloadStatus.value==='downloading'||!qrData.value)return;clearTimeout(qrDownloadTimer.value);qrDownloadStatus.value='downloading';let objectUrl='';try{const response=await fetch(qrData.value);if(!response.ok)throw new Error('QR image conversion failed');const blob=await response.blob();if(!blob.size||blob.type!=='image/png')throw new Error('Invalid QR image');objectUrl=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=objectUrl;anchor.download=qrFilename();anchor.hidden=true;anchor.addEventListener('click',event=>event.stopPropagation(),{once:true});document.body.appendChild(anchor);anchor.click();anchor.remove();const completedUrl=objectUrl;objectUrl='';setTimeout(()=>URL.revokeObjectURL(completedUrl),1000);qrDownloadStatus.value='success';qrDownloadTimer.value=setTimeout(()=>qrDownloadStatus.value='idle',2200)}catch(error){if(objectUrl)URL.revokeObjectURL(objectUrl);qrDownloadStatus.value='error';if(import.meta.env.DEV)console.error('Gallery QR download failed',{groupId:props.group.id,errorName:error?.name||'Error'})}}
function printQrContent(){if(qrData.value)window.print()}
function escapeHtml(value){return String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}
function shareKeydown(event){if(event.key==='Escape'){event.preventDefault();qrOpen.value?closeQr():closeShare();return}const dialog=qrOpen.value?qrDialog.value:shareDialog.value;if(event.key!=='Tab'||!dialog)return;const nodes=[...dialog.querySelectorAll('button:not([disabled]),a[href],input:not([disabled])')];if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
const enabledPermissions=computed(()=>{const p=invitation.value?.permissions||{};return[{key:'find_my_photos',label:'Find My Photos — view permitted matching photos'},{key:'view_highlights',label:'View highlights'},{key:'view_all_photos',label:'View permitted photos and folders'},{key:'favourite',label:'Favourite photos'},{key:'download',label:'Download permitted photos'}].filter(item=>p[item.key])})
const nativeShareSupported=typeof navigator!=='undefined'&&typeof navigator.share==='function'
async function favorite(photo){if(busyFavourites.value.has(photo.id))return;const previous=photo.liked,previousCount=photo.favourites_count;photo.liked=!previous;photo.favourites_count=Math.max(0,previousCount+(photo.liked?1:-1));busyFavourites.value=new Set([...busyFavourites.value,photo.id]);try{const response=await fetch(`/groups/${props.group.id}/photos/${photo.id}/favourite`,{method:photo.liked?'POST':'DELETE',headers:{'Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content}});if(!response.ok)throw new Error('request failed');const data=await response.json();photo.liked=data.is_favourite;photo.favourites_count=data.favourites_count;const tab=props.tabs.find(item=>item.key==='favorites');if(tab)tab.count=Math.max(0,tab.count+(data.is_favourite&&!previous?1:!data.is_favourite&&previous?-1:0));toast.value=data.is_favourite?'Added to favourites':'Removed from favourites';if(props.activeTab==='favorites'&&!data.is_favourite){const index=props.photos.data.findIndex(item=>item.id===photo.id);if(index>=0)props.photos.data.splice(index,1)}}catch{photo.liked=previous;photo.favourites_count=previousCount;toast.value="Couldn’t update favourites. Please try again."}finally{const next=new Set(busyFavourites.value);next.delete(photo.id);busyFavourites.value=next;setTimeout(()=>toast.value='',2400)}}
function downloadCurrentPhoto(photo){if(busyDownloads.value.has(photo.id)||!photo.download_url)return;const anchor=document.createElement('a');busyDownloads.value=new Set([...busyDownloads.value,photo.id]);anchor.href=photo.download_url;anchor.download=(photo.original_filename||`lenspic-photo-${photo.id}.jpg`).replace(/[\\/]/g,'-');anchor.hidden=true;document.body.appendChild(anchor);anchor.click();anchor.remove();toast.value='Download started';setTimeout(()=>{const next=new Set(busyDownloads.value);next.delete(photo.id);busyDownloads.value=next;toast.value=''},1200)}
function openFilePicker(){fileInput.value?.click()}
function chooseFiles(files){let duplicates=0,rejected=0;for(const file of [...files]){if(uploadFiles.value.length>=maxUploadBatchFiles.value){rejected++;continue}if(uploadFiles.value.some(item=>item.file.name===file.name&&item.file.size===file.size&&item.file.lastModified===file.lastModified)){duplicates++;continue}const supported=['image/jpeg','image/png','image/webp'].includes(file.type)&&/\.(jpe?g|png|webp)$/i.test(file.name);uploadFiles.value.push({file,url:supported&&file.size<=maxUploadFileBytes.value?URL.createObjectURL(file):null,error:!supported?'Only JPG, JPEG, PNG and WebP photos are supported.':file.size>maxUploadFileBytes.value?`${file.name} exceeds the maximum size of ${maxUploadFileMb.value} MB.`:''})}const messages=[];if(duplicates)messages.push(`${duplicates} duplicate ${duplicates===1?'photo was':'photos were'} ignored.`);if(rejected)messages.push(`You can upload up to ${maxUploadBatchFiles.value} photos at a time. Remove some photos and try again.`);uploadError.value=messages.join(' ');uploadOpen.value=true}
function handleFiles(event){chooseFiles(event.target.files);if(fileInput.value)fileInput.value.value=''}
function dropFiles(event){dragActive.value=false;chooseFiles(event.dataTransfer?.files||[])}
function removeUpload(index){const item=uploadFiles.value[index];if(item?.url)URL.revokeObjectURL(item.url);uploadFiles.value.splice(index,1)}
function clearUploadFiles(){uploadFiles.value.forEach(item=>{if(item.url)URL.revokeObjectURL(item.url)});uploadFiles.value=[];if(fileInput.value)fileInput.value.value=''}
function uploadHttpError(request){if(request.status===413)return'The server rejected this upload because the request was too large. Please retry the failed photo.';if(request.status===419)return'Your session expired. Refresh the page and try again.';if(request.status===403)return'You do not have permission to upload to this gallery.';if(request.status===507)return'Your current storage limit has been reached.';if(request.status===422)return request.response?.message||'One or more photos could not be validated.';return request.response?.message||'Photo upload is temporarily unavailable. Please try again shortly.'}
async function startUpload(){if(transferring.value||!uploadFiles.value.length||uploadFiles.value.some(item=>item.error))return;const items=[...uploadFiles.value];items.forEach(item=>{item.progress=0;item.transportError=''});transferring.value=true;transferProgress.value=0;uploadError.value='';uploadBatchIds.value=[];let cursor=0,uploaded=0;const updateOverall=()=>{transferProgress.value=Math.round(items.reduce((sum,item)=>sum+(item.progress||0),0)/items.length)};const uploadOne=item=>new Promise(resolve=>{const data=new FormData();data.append('photos[]',item.file);const request=new XMLHttpRequest();activeRequests.value.add(request);request.open('POST',`/groups/${props.group.id}/photos`);request.responseType='json';request.setRequestHeader('Accept','application/json');request.setRequestHeader('X-CSRF-TOKEN',document.querySelector('meta[name="csrf-token"]').content);request.upload.onprogress=e=>{if(e.lengthComputable){item.progress=Math.round(e.loaded/e.total*100);updateOverall()}};const finish=()=>{activeRequests.value.delete(request);resolve()};request.onload=()=>{if(request.status>=200&&request.status<300){item.progress=100;uploaded++;uploadBatchIds.value.push(request.response.upload_reference)}else{item.transportError=uploadHttpError(request);item.error=item.transportError}updateOverall();finish()};request.onerror=()=>{item.transportError='The failed photo could not be uploaded. Please retry it.';item.error=item.transportError;finish()};request.onabort=()=>{item.transportError='Upload cancelled.';item.error=item.transportError;finish()};request.send(data)});const worker=async()=>{while(cursor<items.length&&transferring.value){const item=items[cursor++];await uploadOne(item)}};await Promise.all(Array.from({length:Math.min(uploadConcurrency.value,items.length)},worker));transferring.value=false;const failed=items.filter(item=>item.transportError),accepted=items.filter(item=>!item.transportError);accepted.forEach(item=>{if(item.url)URL.revokeObjectURL(item.url)});uploadFiles.value=failed;uploadError.value=failed.length?`${failed.length} ${failed.length===1?'photo failed':'photos failed'} to upload. Retry the failed photos individually.`:'';if(uploadBatchIds.value.length){upload.value={uuid:uploadBatchIds.value[0],batchUuids:[...uploadBatchIds.value],total_files:uploaded,completed_files:0,failed_files:0,pending_files:uploaded,processing_files:0,progress_percentage:0,files:[]};schedulePoll(200)}}
function cancelTransfer(){transferring.value=false;activeRequests.value.forEach(request=>request.abort());activeRequests.value.clear();uploadError.value='Upload cancelled.'}
async function retryTransport(index){if(transferring.value)return;const item=uploadFiles.value[index];if(!item?.transportError)return;const others=uploadFiles.value.filter((_,itemIndex)=>itemIndex!==index);item.error='';item.transportError='';uploadFiles.value=[item];await startUpload();uploadFiles.value=[...others,...uploadFiles.value]}
function closeUpload(){if(transferring.value)cancelTransfer();uploadOpen.value=false}
function uploadMore(){upload.value=null;uploadError.value='';transferProgress.value=0;uploadOpen.value=true}
function addReadyPhotos(data){for(const item of data.files||[]){const photo=item.photo;if(!photo||seenReady.has(photo.id))continue;seenReady.add(photo.id);const exists=props.photos.data.some(current=>current.id===photo.id);if(!exists){const all=props.tabs.find(tab=>tab.key==='all');if(all)all.count++;const folder=props.tabs.find(tab=>tab.key===`folder-${photo.folder_id}`);if(folder)folder.count++;props.group.photos_count++;if(props.activeTab==='all'||props.activeTab===`folder-${photo.folder_id}`)props.photos.data.unshift(photo)}}}
async function poll(){if(!upload.value||document.hidden)return schedulePoll(3000);try{const ids=upload.value.batchUuids||[upload.value.uuid];const responses=await Promise.all(ids.map(id=>fetch(`/processing/batches/${id}`,{headers:{Accept:'application/json'}})));if(responses.some(response=>!response.ok))throw new Error();const batches=await Promise.all(responses.map(response=>response.json()));batches.forEach(addReadyPhotos);const total=field=>batches.reduce((sum,batch)=>sum+Number(batch[field]||0),0),terminal=batches.every(batch=>['completed','completed_with_errors','failed','cancelled'].includes(batch.status));upload.value={...upload.value,total_files:total('total_files'),completed_files:total('completed_files'),failed_files:total('failed_files'),pending_files:total('pending_files'),processing_files:total('processing_files'),progress_percentage:batches.length?Math.round(batches.reduce((sum,batch)=>sum+Number(batch.progress_percentage||0),0)/batches.length):0,stalled:batches.some(batch=>batch.stalled),last_activity_at:batches.map(batch=>batch.last_activity_at).filter(Boolean).sort().at(-1),files:batches.flatMap(batch=>batch.files||[])};if(terminal){if(upload.value.failed_files)toast.value=`${upload.value.completed_files} photos are ready. We couldn’t process ${upload.value.failed_files}.`;else toast.value=`${upload.value.completed_files} photos uploaded successfully and added to your gallery.`;return}schedulePoll()}catch{schedulePoll(5000)}}
function schedulePoll(delay=3000){clearTimeout(pollTimer.value);pollTimer.value=setTimeout(poll,delay)}
async function restoreUpload(){try{const response=await fetch(`/groups/${props.group.id}/processing/active`,{headers:{Accept:'application/json'}});if(response.ok){const data=await response.json();if(data.upload){upload.value=data.upload;addReadyPhotos(data.upload);schedulePoll()}}}catch{}}
async function retryFailed(){if(!upload.value)return;const ids=upload.value.batchUuids||[upload.value.uuid];await Promise.all(ids.map(id=>fetch(`/processing/batches/${id}/retry`,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content}})));schedulePoll(200)}
function viewerUrl(photo){return `${photo.viewer_url}?${new URLSearchParams({tab:props.activeTab,page:String(props.photos.current_page||1)})}`}
function rememberGalleryPosition(photo){sessionStorage.setItem(scrollKey,JSON.stringify({y:window.scrollY,photoId:photo.id}))}
onMounted(()=>{try{selected.value=JSON.parse(sessionStorage.getItem(storageKey)||'[]');const saved=JSON.parse(sessionStorage.getItem(scrollKey)||'null');if(saved?.y!=null)requestAnimationFrame(()=>{window.scrollTo({top:saved.y,behavior:'instant'});requestAnimationFrame(()=>document.querySelector(`a[href*="/photos/${saved.photoId}"]`)?.focus({preventScroll:true}))})}catch{selected.value=[]}if(props.canUpload)restoreUpload();window.addEventListener('keydown',shareKeydown)})
onBeforeUnmount(()=>{clearTimeout(pollTimer.value);clearTimeout(inviteCopyTimer.value);clearTimeout(qrCopyTimer.value);clearTimeout(qrDownloadTimer.value);activeRequests.value.forEach(request=>request.abort());clearUploadFiles();window.removeEventListener('keydown',shareKeydown);document.body.style.overflow=''})
watch(selected,value=>sessionStorage.setItem(storageKey,JSON.stringify(value)),{deep:true})
watch(shareOpen,value=>{document.body.style.overflow=value?'hidden':''})
</script>

<template><AppShell><Head :title="group.name"/><div :class="['-mx-4 -mt-4 md:-mx-7 md:-mt-7',shareOpen?'share-dialog-open':'']">
  <header class="sticky top-0 z-30 grid min-h-[92px] grid-cols-[1fr_auto] items-center gap-4 border-b border-slate-200 bg-white/95 px-4 py-3 backdrop-blur md:grid-cols-3 md:px-7">
    <div class="flex min-w-0 items-center gap-3"><Link href="/groups" class="grid h-10 w-10 shrink-0 place-items-center hover:bg-slate-100" aria-label="Back to groups">←</Link><div class="min-w-0"><p class="text-[11px] uppercase tracking-wider text-slate-400">Album by</p><p class="truncate text-sm font-semibold">{{group.owner_name||'LensPic Studio'}}</p></div></div>
    <div class="col-span-2 row-start-2 text-center md:col-span-1 md:col-start-2 md:row-start-1"><h1 class="truncate font-display text-xl font-bold md:text-2xl">{{group.name}}</h1><p class="mt-1 text-xs text-slate-500">{{eventDate}}</p></div>
    <div class="flex items-center justify-end gap-1 md:col-start-3"><Link v-if="group.face_recognition_enabled" :href="`/groups/${group.id}/find-my-photos`" class="btn-secondary">Find My Photos</Link><button class="px-3 py-2 text-sm font-semibold md:hidden" @click="selectionMode=!selectionMode">{{selectionMode?'Done':'Select'}}</button><button v-if="canUpload" ref="uploadTrigger" type="button" class="min-h-11 bg-indigo px-3 text-sm font-semibold text-white" @click="uploadOpen=true">＋ <span class="hidden sm:inline">Upload photos</span></button><Link v-if="canManage" :href="`/groups/${group.id}/settings`" class="grid h-11 w-11 place-items-center hover:bg-slate-100 focus-visible:ring-2 focus-visible:ring-indigo" title="Photo settings" aria-label="Photo settings"><svg aria-hidden="true" viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2.83 2.83-.06-.06A1.7 1.7 0 0 0 15 19.4a1.7 1.7 0 0 0-1 .6 1.7 1.7 0 0 0-.4 1.1V21h-4v-.09A1.7 1.7 0 0 0 8.6 19.4a1.7 1.7 0 0 0-1.88.34l-.06.06-2.83-2.83.06-.06A1.7 1.7 0 0 0 4.6 15a1.7 1.7 0 0 0-1.6-1H3v-4h.09A1.7 1.7 0 0 0 4.6 9a1.7 1.7 0 0 0-.34-1.88l-.06-.06 2.83-2.83.06.06A1.7 1.7 0 0 0 9 4.6a1.7 1.7 0 0 0 1-.6 1.7 1.7 0 0 0 .4-1.1V3h4v.09A1.7 1.7 0 0 0 15.4 4.6a1.7 1.7 0 0 0 1.88-.34l.06-.06 2.83 2.83-.06.06A1.7 1.7 0 0 0 19.4 9a1.7 1.7 0 0 0 1.6 1h.09v4H21a1.7 1.7 0 0 0-1.6 1z"/></svg></Link><button v-if="group.can_share_group" type="button" class="grid h-11 w-11 place-items-center hover:bg-slate-100 focus-visible:ring-2 focus-visible:ring-indigo" title="Share Group" aria-label="Share Group" :disabled="sharing" @click="shareCurrentGroup"><span v-if="sharing">…</span><svg v-else aria-hidden="true" viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.6 10.5 6.8-4"/><path d="m8.6 13.5 6.8 4"/></svg></button><Link v-if="canManage" :href="`/groups/${group.id}/operations`" class="grid h-11 w-11 place-items-center hover:bg-slate-100 focus-visible:ring-2 focus-visible:ring-indigo" title="Downloads and processing" aria-label="Downloads and processing"><svg aria-hidden="true" viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="m7 10 5 5 5-5"/><path d="M12 15V3"/></svg></Link></div>
