  <aside v-if="Object.keys(branding||{}).length" class="flex flex-wrap items-center gap-x-4 gap-y-2 border-b border-slate-200 bg-white px-4 py-3 text-sm md:px-7"><img v-if="branding.logo_url" :src="branding.logo_url" :alt="`${branding.business_name||'Business'} logo`" class="h-8 max-w-32 object-contain"><strong v-if="branding.business_name">{{branding.business_name}}</strong><a v-if="branding.phone" :href="`tel:${branding.phone.replace(/\s/g,'')}`" class="text-indigo">{{branding.phone}}</a><a v-if="branding.email" :href="`mailto:${branding.email}`" class="text-indigo">{{branding.email}}</a><a v-if="branding.website" :href="branding.website" target="_blank" rel="noopener" class="text-indigo">Website</a><a v-if="branding.instagram_url" :href="branding.instagram_url" target="_blank" rel="noopener" class="text-indigo">Instagram</a><a v-if="branding.facebook_url" :href="branding.facebook_url" target="_blank" rel="noopener" class="text-indigo">Facebook</a></aside>
  <div v-if="toast" role="status" aria-live="polite" class="fixed bottom-5 left-1/2 z-50 -translate-x-1/2 bg-ink px-4 py-3 text-sm font-semibold text-white shadow-xl">{{toast}}</div>
  <div v-if="shareOpen" class="fixed inset-0 z-50 grid place-items-center overflow-y-auto bg-slate-950/55 p-3 backdrop-blur-sm sm:p-6" @click.self="closeShare"><section ref="shareDialog" class="my-auto max-h-[calc(100vh-24px)] w-full max-w-4xl overflow-y-auto rounded-3xl bg-white p-5 shadow-2xl sm:p-8" role="dialog" aria-modal="true" aria-labelledby="share-group-title"><div class="flex items-center justify-between gap-4"><div><p class="text-xs font-bold uppercase tracking-[.16em] text-indigo">LensPic access</p><h2 id="share-group-title" class="mt-1 font-display text-2xl font-bold">Share Group Invite</h2></div><button type="button" class="grid h-11 w-11 shrink-0 place-items-center rounded-full text-2xl hover:bg-slate-100" title="Close" aria-label="Close Share Group Invite" :disabled="sharing" @click="closeShare">×</button></div>
    <div v-if="sharing" class="grid min-h-64 place-items-center" aria-live="polite"><div class="text-center"><span class="mx-auto block h-9 w-9 animate-spin rounded-full border-4 border-indigo/20 border-t-indigo"></span><p class="mt-4 text-sm text-slate-600">Preparing a secure invitation…</p></div></div>
