    <template v-else-if="invitation"><article class="mt-6 rounded-2xl border border-slate-200 bg-slate-50/70 p-5 sm:p-6"><div class="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><p class="text-sm text-slate-500">Access type</p><h3 class="mt-1 text-xl font-bold">Full Access</h3></div><button type="button" class="flex min-h-11 items-center gap-2 self-start rounded-xl border border-indigo/20 bg-indigo/5 px-4 font-mono font-bold tracking-[.16em] text-indigo" title="Copy invitation code" aria-label="Copy invitation code" @click="copyText(invitation.code,'Code copied')"><svg aria-hidden="true" viewBox="0 0 24 24" class="h-5 w-5" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>{{invitation.code}}</button></div><ul class="mt-5 grid gap-3 sm:grid-cols-2"><li v-for="permission in enabledPermissions" :key="permission.key" class="flex items-start gap-3 text-sm"><svg aria-hidden="true" viewBox="0 0 24 24" class="mt-0.5 h-5 w-5 shrink-0 text-indigo" fill="none" stroke="currentColor" stroke-width="2.2"><path d="m5 12 4 4L19 6"/></svg><span>{{permission.label}}</span></li></ul><p class="mt-4 text-sm text-amber-800">Treat this private Group link as an access credential. Share only with intended recipients. The photographer can revoke it in Group invitation settings.</p><p v-if="invitation.expires_at" class="mt-5 text-xs text-slate-500">Expires {{new Date(invitation.expires_at).toLocaleString()}}</p><div class="mt-6 flex flex-col gap-3 sm:flex-row"><button type="button" class="btn-primary flex min-h-11 flex-1 items-center justify-center gap-2" :disabled="inviteCopying" aria-describedby="invite-copy-status" @click="copyInviteLink"><svg v-if="inviteCopied" aria-hidden="true" viewBox="0 0 24 24" class="h-5 w-5" fill="none" stroke="currentColor" stroke-width="2.2"><path d="m5 12 4 4L19 6"/></svg><svg v-else aria-hidden="true" viewBox="0 0 24 24" class="h-5 w-5" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>{{inviteCopied?'Link copied':'Invite Links'}}</button><button type="button" class="btn-secondary min-h-11 flex-1" @click="printQr">Print QR</button></div><div class="mt-3 flex flex-col gap-3 sm:flex-row"><button type="button" class="min-h-11 flex-1 rounded-xl bg-emerald-700 px-4 py-3 font-semibold text-white" @click="shareGroupWhatsApp">Share on WhatsApp</button><button v-if="nativeShareSupported" type="button" class="btn-secondary min-h-11 flex-1" @click="shareThroughDevice">Share through device</button></div><p id="invite-copy-status" class="mt-3 min-h-5 text-sm font-semibold" :class="inviteCopyError?'text-red-700':'text-indigo'" aria-live="polite">{{inviteCopyError||(inviteCopied?'Link copied':'')}}</p>
      <p v-if="copyFeedback" class="mt-3 text-sm font-semibold text-indigo" aria-live="polite">{{copyFeedback}}</p></article>
      <section class="mt-6 flex flex-col gap-4 rounded-2xl bg-gradient-to-r from-indigo/10 to-violet-50 p-5 sm:flex-row sm:items-center"><div class="grid h-16 w-16 shrink-0 place-items-center rounded-2xl bg-white text-indigo shadow-sm" aria-hidden="true"><svg viewBox="0 0 48 48" class="h-10 w-10" fill="none" stroke="currentColor" stroke-width="2"><rect x="7" y="9" width="34" height="27" rx="5"/><path d="m12 31 9-9 6 6 4-4 6 7"/><circle cx="31" cy="17" r="3"/></svg></div><div class="min-w-0 flex-1"><h3 class="font-bold">How to join this Group</h3><p class="mt-1 text-sm text-slate-600">Quick joining guide</p></div><button type="button" class="btn-secondary min-h-11" @click="guideOpen=!guideOpen">Share Guide</button></section><ol v-if="guideOpen" class="mt-4 list-decimal space-y-2 rounded-2xl border border-slate-200 p-5 pl-10 text-sm text-slate-700"><li>Open the invitation link.</li><li>Enter the invitation code if requested.</li><li>Confirm authorized Group access.</li><li>Browse permitted photos.</li><li v-if="invitation.permissions.find_my_photos">Optionally provide consent to use Find My Photos.</li></ol>
    </template></section>
    <div v-if="qrOpen" class="qr-popup-backdrop fixed inset-0 z-[60] grid place-items-center overflow-y-auto bg-slate-950/65 p-3 backdrop-blur-[2px] sm:p-6" @click.self="closeQr"><section ref="qrDialog" class="qr-print-card my-auto max-h-[calc(100vh-24px)] w-full max-w-xl overflow-y-auto rounded-3xl bg-white p-5 text-center shadow-2xl sm:p-8" role="dialog" aria-modal="true" aria-labelledby="qr-popup-title"><div class="qr-no-print flex items-center justify-between gap-4 text-left"><h2 id="qr-popup-title" class="font-display text-2xl font-bold">Group Invitation QR</h2><button type="button" class="grid h-11 w-11 shrink-0 place-items-center rounded-full text-2xl hover:bg-slate-100" title="Close QR Code" aria-label="Close QR Code popup" @click="closeQr">×</button></div><div class="mt-4 text-2xl font-extrabold text-ink">Lens<span class="text-indigo">Pic</span></div><h3 class="mt-3 text-xl font-bold">{{group.name}}</h3><div class="mx-auto mt-5 grid aspect-square w-full max-w-[360px] place-items-center rounded-2xl border border-slate-200 bg-white p-3"><span v-if="!qrData" class="text-sm text-slate-500">Generating QR code…</span><img v-else :src="qrData" class="h-full w-full object-contain" alt="QR code for Group invitation"></div><p class="mt-4 font-semibold">Scan this QR code to join the Group</p><p class="mt-3 text-sm text-slate-500">Invitation code</p><div class="mx-auto mt-1 inline-flex rounded-xl bg-indigo/5 px-5 py-3 font-mono text-xl font-bold tracking-[.18em] text-indigo">{{invitation.code}}</div><div class="qr-no-print relative z-10 mt-3 min-h-12" aria-live="polite"><div v-if="qrDownloadStatus==='success'" class="qr-copy-feedback flex min-h-11 items-center justify-center gap-2 rounded-xl border border-emerald-200 bg-emerald-50 px-4 text-sm font-semibold text-emerald-800" role="status"><svg aria-hidden="true" viewBox="0 0 24 24" class="h-5 w-5 shrink-0" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/></svg>QR downloaded</div><div v-else-if="qrDownloadStatus==='error'" class="flex min-h-11 items-center justify-center rounded-xl border border-red-200 bg-red-50 px-4 text-sm font-semibold text-red-800" role="alert">Could not download the QR. Please try again.</div><div v-else-if="qrCopyStatus==='success'" class="qr-copy-feedback flex min-h-11 items-center justify-center gap-2 rounded-xl border border-emerald-200 bg-emerald-50 px-4 text-sm font-semibold text-emerald-800" role="status"><svg aria-hidden="true" viewBox="0 0 24 24" class="h-5 w-5 shrink-0" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/></svg>Link copied</div><div v-else-if="qrCopyStatus==='error'" class="flex min-h-11 items-center justify-center rounded-xl border border-red-200 bg-red-50 px-4 text-sm font-semibold text-red-800" role="alert">Could not copy the link. Please try again.</div></div><div class="qr-no-print mt-2 grid gap-3 sm:grid-cols-3"><button type="button" class="btn-secondary flex min-h-11 items-center justify-center gap-2" :disabled="qrCopyStatus==='copying'" @click="copyQrLink"><svg v-if="qrCopyStatus==='success'" aria-hidden="true" viewBox="0 0 24 24" class="h-5 w-5" fill="none" stroke="currentColor" stroke-width="2"><path d="m5 12 4 4L19 6"/></svg><svg v-else aria-hidden="true" viewBox="0 0 24 24" class="h-5 w-5" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>{{qrCopyStatus==='copying'?'Copying…':qrCopyStatus==='success'?'Copied':'Copy Link'}}</button><button type="button" class="btn-secondary min-h-11" :disabled="!qrData||qrDownloadStatus==='downloading'" @click.stop.prevent="downloadInvitationQr">{{qrDownloadStatus==='downloading'?'Downloading…':qrDownloadStatus==='success'?'Downloaded':'Download QR'}}</button><button type="button" class="btn-primary min-h-11" :disabled="!qrData" @click="printQrContent">Print QR</button></div></section></div>
  </div>
  <nav class="flex overflow-x-auto border-b border-slate-200 bg-white px-4 md:px-7" aria-label="Gallery folders"><Link v-for="tab in tabs" :key="tab.key" :href="`/groups/${group.id}/gallery?tab=${tab.key}`" preserve-scroll :class="['shrink-0 border-b-2 px-4 py-4 text-sm font-semibold',activeTab===tab.key?'border-indigo text-indigo':'border-transparent text-slate-500 hover:text-ink']">{{tab.label}} <span class="ml-1 text-xs opacity-60">{{tab.count}}</span></Link></nav>
  <UploadModal :open="canUpload&&uploadOpen" :busy="transferring" :trigger="uploadTrigger" title="Upload photos" @close="closeUpload"><div class="overflow-y-auto p-5 pb-[max(20px,env(safe-area-inset-bottom))] sm:p-7"><div class="flex items-start justify-between gap-4"><div><h2 class="text-lg font-bold">Upload photos to {{group.name}}</h2><p class="mt-1 text-sm text-slate-500">JPG, JPEG, PNG or WebP · maximum {{maxUploadFileMb}} MB each · up to {{maxUploadBatchFiles}} photos</p><p class="mt-2 text-sm text-slate-500">Your photos are automatically optimized for fast loading and excellent quality.</p></div><button v-if="!transferring" type="button" class="p-2 text-xl" aria-label="Close upload modal" @click="closeUpload">×</button></div><div v-if="!transferring&&!upload" :class="['mt-4 grid min-h-44 cursor-pointer place-items-center border-2 border-dashed bg-white p-6 text-center transition',dragActive?'border-indigo bg-indigo/5':'border-indigo/30 hover:border-indigo']" @click="openFilePicker" @dragenter.prevent="dragActive=true" @dragover.prevent="dragActive=true" @dragleave.prevent="dragActive=false" @drop.prevent.stop="dropFiles"><div class="pointer-events-none"><span class="text-3xl" aria-hidden="true">⇧</span><strong class="mt-2 block text-lg">Drag & drop photos here</strong><span class="my-2 block text-sm text-slate-400">or</span><button type="button" class="btn-primary pointer-events-auto min-h-11 px-6" @click.stop="openFilePicker">Choose Photos</button><p class="mt-3 text-xs text-slate-500">JPG, JPEG, PNG or WebP · maximum {{maxUploadFileMb}} MB each · up to {{maxUploadBatchFiles}} photos</p><input ref="fileInput" type="file" accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp" multiple class="sr-only" aria-label="Choose photos to upload" @change="handleFiles"></div></div><div v-if="!transferring&&!upload&&!uploadFiles.length" class="mt-4 flex justify-end"><button type="button" class="btn-primary" disabled>Upload Photos</button></div><div v-if="uploadFiles.length" class="mt-4"><div class="flex items-center justify-between"><p class="text-sm font-semibold">{{uploadFiles.length}} / {{maxUploadBatchFiles}} photos selected</p><button v-if="!transferring" class="text-sm text-slate-500 underline" @click="clearUploadFiles">Clear</button></div><ul class="mt-2 max-h-48 divide-y divide-slate-100 overflow-auto bg-white"><li v-for="(item,index) in uploadFiles.slice(0,30)" :key="item.file.name+item.file.size" class="flex items-center gap-3 p-2"><img v-if="item.url" :src="item.url" alt="" class="h-10 w-10 object-cover"><span v-else class="grid h-10 w-10 place-items-center bg-red-50 text-red-700">!</span><span class="min-w-0 flex-1 truncate text-sm">{{item.file.name}} <small class="text-slate-400">{{(item.file.size/1048576).toFixed(1)}} MB</small><span v-if="item.error" class="block text-xs text-red-700">{{item.error}}</span></span><button v-if="!transferring&&item.transportError" class="h-11 px-3 text-sm font-semibold text-indigo" aria-label="Retry failed photo" @click="retryTransport(index)">Retry</button><button v-if="!transferring" class="h-11 px-3 text-sm" :aria-label="`Remove ${item.file.name}`" @click="removeUpload(index)">Remove</button></li></ul><p v-if="uploadFiles.length>30" class="mt-2 text-xs text-slate-500">Showing 30 of {{uploadFiles.length}} selected photos.</p><div class="mt-4 flex gap-3"><button class="btn-primary" :disabled="transferring||uploadFiles.some(item=>item.error)" @click="startUpload">Upload {{uploadFiles.length}} photos</button><button v-if="!transferring" class="btn-secondary" @click="clearUploadFiles">Cancel</button></div></div><UploadProgress v-if="transferring" class="mt-5" :value="transferProgress" label="Uploading photos" :detail="`${transferProgress}% transferred`"/><button v-if="transferring" class="mt-3 text-sm text-red-700 underline" @click="cancelTransfer">Cancel upload</button><div v-if="upload&&!transferring" class="mt-5"><div v-if="upload.stalled" class="mb-4 border border-amber-300 bg-amber-50 p-3 text-sm text-amber-900" role="alert"><strong>Processing is taking longer than expected.</strong><p class="mt-1">Your original is safe. Refresh the server status or retry after the worker is available.</p><button type="button" class="mt-2 font-semibold underline" @click="poll">Retry status check</button></div><p v-if="upload.failed_files" class="mb-3 font-semibold text-red-700">{{upload.failed_files}} {{upload.failed_files===1?'photo':'photos'}} could not be prepared.</p><UploadProgress :value="upload.progress_percentage" :tone="upload.failed_files?'warning':upload.progress_percentage===100?'success':'brand'" label="Preparing your gallery" :detail="`${upload.completed_files} of ${upload.total_files} photos ready · ${upload.total_files-upload.completed_files-upload.failed_files} remaining${upload.failed_files?` · ${upload.failed_files} need attention`:''}`"/><p v-if="upload.pending_files||upload.processing_files" class="mt-3 text-sm text-slate-500">Your photos are being prepared here automatically. You can safely leave this page—we’ll continue in the background.</p><div class="mt-4 flex flex-wrap gap-3"><button v-if="upload.failed_files" class="btn-secondary" @click="retryFailed">Try failed photos again</button><button v-if="upload.progress_percentage===100" class="btn-primary" @click="closeUpload">View photos</button><button v-if="upload.progress_percentage===100" class="btn-secondary" @click="uploadMore">Upload more</button><button class="btn-secondary" @click="closeUpload">Close</button></div></div><p v-if="uploadError" class="mt-4 text-sm font-semibold text-red-700" role="alert">{{uploadError}}</p></div></UploadModal>
  <button v-if="upload&&!uploadOpen&&upload.progress_percentage<100" class="sticky top-[92px] z-20 w-full border-b border-indigo/15 bg-indigo/5 px-4 py-3 text-left" @click="uploadOpen=true"><span class="flex items-center justify-between text-sm font-semibold"><span>Preparing your gallery · {{upload.completed_files}} of {{upload.total_files}} ready</span><span>View progress</span></span><span class="mt-2 block h-1.5 overflow-hidden rounded-full bg-indigo/10"><span class="block h-full bg-indigo transition-all" :style="{width:`${upload.progress_percentage}%`}"></span></span></button>
  <div v-if="selected.length" class="sticky top-[92px] z-20 flex flex-wrap items-center gap-3 border-b border-indigo/15 bg-indigo px-4 py-3 text-white md:px-7"><strong>{{selected.length}} selected</strong><button class="text-sm underline" @click="toggleLoaded">{{allLoadedSelected?'Deselect loaded photos':`Select all ${photos.data.length} loaded`}}</button><span class="text-xs text-white/70">Current page</span><button class="ml-auto border border-white/30 px-3 py-2 text-sm font-semibold hover:bg-white/10" :disabled="exportForm.processing" @click="makeExport">{{exportForm.processing?'Preparing download…':'Download'}}</button><button class="px-3 py-2 text-sm font-semibold" @click="clearSelection">Clear</button></div>
  <main class="bg-white p-1"><StateCard v-if="!photos.data.length" class="m-6" title="No photos here yet" message="Choose another folder, or upload photographs to this group."/>
    <div v-else class="photo-grid columns-1 gap-1 min-[390px]:columns-2 md:columns-3 xl:columns-5" aria-label="Group photos"><figure v-for="photo in photos.data" :key="photo.id" :class="['group/photo relative mb-1 break-inside-avoid overflow-hidden bg-slate-100',selected.includes(photo.id)?'ring-3 ring-inset ring-indigo after:pointer-events-none after:absolute after:inset-0 after:bg-indigo/10':'']" :style="{aspectRatio:`${photo.width} / ${photo.height}`}"><Link :href="viewerUrl(photo)" preserve-scroll class="block h-full w-full" @click="rememberGalleryPosition(photo)"><img :src="photo.url" :alt="photo.original_filename" loading="lazy" decoding="async" class="h-full w-full object-cover" :width="photo.width" :height="photo.height"></Link><PhotoSelector :checked="selected.includes(photo.id)" :visible="selectionMode||selected.length>0" :label="`${selected.includes(photo.id)?'Deselect':'Select'} photo ${photo.original_filename}`" @change="togglePhoto(photo,$event)"/><div class="absolute right-1 top-1 z-10 flex gap-1 opacity-100 transition md:opacity-0 md:group-hover/photo:opacity-100 md:group-focus-within/photo:opacity-100"><button v-if="group.favourites_enabled" type="button" :disabled="busyFavourites.has(photo.id)" :aria-pressed="photo.liked" :aria-label="photo.liked?'Remove from favourites':'Add to favourites'" :class="['grid h-11 w-11 place-items-center bg-black/45 text-white shadow transition hover:scale-105 hover:bg-white hover:text-indigo focus-visible:ring-2 focus-visible:ring-white',photo.liked?'text-coral':'']" @click.stop.prevent="favorite(photo)"><svg viewBox="0 0 24 24" :fill="photo.liked?'currentColor':'none'" class="h-6 w-6" aria-hidden="true"><path d="M20.8 4.8a5.5 5.5 0 0 0-7.8 0L12 5.9l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.4a5.5 5.5 0 0 0 0-7.8Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/></svg></button><button v-if="photo.download_url" type="button" class="grid h-11 w-11 place-items-center bg-black/50 text-white" aria-label="Download photo" title="Download photo" :disabled="busyDownloads.has(photo.id)" @click.stop.prevent="downloadCurrentPhoto(photo)"><span v-if="busyDownloads.has(photo.id)">…</span><svg v-else aria-hidden="true" viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="m7 10 5 5 5-5"/><path d="M12 15V3"/></svg></button></div></figure></div>
    <div v-if="photos.prev_page_url||photos.next_page_url" class="flex items-center justify-center gap-3 border-t border-slate-100 py-8"><Link v-if="photos.prev_page_url" :href="photos.prev_page_url" preserve-scroll class="btn-secondary">Previous</Link><span class="text-sm text-slate-500">Page {{photos.current_page}} of {{photos.last_page}}</span><Link v-if="photos.next_page_url" :href="photos.next_page_url" preserve-scroll class="btn-primary">Load more</Link></div>
  </main>
</div></AppShell></template>

